set -eu
cat > inspect_rds_metadata.R <<'RS'
args <- commandArgs(trailingOnly = TRUE)
obj <- readRDS(args[[1]])
con <- file(args[[2]], open = "wt")
on.exit(close(con), add = TRUE)

emit <- function(label, value) {
  rendered <- paste(capture.output(dput(value)), collapse = "\n")
  writeLines(paste0(label, "\t", rendered), con)
}

writeLines(paste0("class\t", paste(class(obj), collapse = "|")), con)
writeLines(paste0("isS4\t", isS4(obj)), con)
if (isS4(obj)) {
  writeLines(paste0("slot_names\t", paste(slotNames(obj), collapse = "|")), con)
  for (nm in slotNames(obj)) {
    val <- slot(obj, nm)
    writeLines(paste0("slot_class_", nm, "\t", paste(class(val), collapse = "|")), con)
  }
  if ("metadata" %in% slotNames(obj)) {
    emit("slot_metadata", slot(obj, "metadata"))
  }
  if ("elementMetadata" %in% slotNames(obj)) {
    em <- slot(obj, "elementMetadata")
    writeLines(paste0("elementMetadata_class\t", paste(class(em), collapse = "|")), con)
    if (isS4(em) && "metadata" %in% slotNames(em)) {
      emit("elementMetadata_metadata", slot(em, "metadata"))
    }
  }
}
emit("attributes", attributes(obj))
if (requireNamespace("S4Vectors", quietly = TRUE)) {
  emit("S4Vectors_metadata", tryCatch(S4Vectors::metadata(obj), error = function(e) paste0("ERROR: ", conditionMessage(e))))
}
RS
